#include <vector>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
    int ans = 0;
    std::vector<int> dfs(TreeNode* node, int distance) {
        if (!node) return {};
        if (!node->left && !node->right) return {1};
        auto leftD = dfs(node->left, distance);
        auto rightD = dfs(node->right, distance);
        for (int d1 : leftD) {
            for (int d2 : rightD) {
                if (d1 + d2 <= distance) ans++;
            }
        }
        std::vector<int> res;
        for (int d : leftD) if (d + 1 < distance) res.push_back(d + 1);
        for (int d : rightD) if (d + 1 < distance) res.push_back(d + 1);
        return res;
    }
public:
    int countPairs(TreeNode* root, int distance) {
        ans = 0;
        dfs(root, distance);
        return ans;
    }
};

import java.util.*;

class Solution {
    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode(int x) { val = x; }
    }
    int ans = 0;
    private List<Integer> dfs(TreeNode node, int distance) {
        if (node == null) return new ArrayList<>();
        if (node.left == null && node.right == null) {
            List<Integer> leaf = new ArrayList<>();
            leaf.add(1);
            return leaf;
        }
        List<Integer> leftD = dfs(node.left, distance);
        List<Integer> rightD = dfs(node.right, distance);
        for (int d1 : leftD) {
            for (int d2 : rightD) {
                if (d1 + d2 <= distance) ans++;
            }
        }
        List<Integer> res = new ArrayList<>();
        for (int d : leftD) if (d + 1 < distance) res.add(d + 1);
        for (int d : rightD) if (d + 1 < distance) res.add(d + 1);
        return res;
    }
    public int countPairs(TreeNode root, int distance) {
        ans = 0;
        dfs(root, distance);
        return ans;
    }
}

